import{loadProducts,getProductById}from"./products.js";const params=new URLSearchParams(window.location.search);const productId=Number(params.get("id"));const breadcrumb=document.getElementById("breadcrumb");const backBtn=document.getElementById("back-btn");const galleryMain=document.getElementById("gallery-main");const galleryTitle=document.getElementById("gallery-title");const galleryThumbs=document.getElementById("gallery-thumbs");const productTag=document.getElementById("product-tag");const productName=document.getElementById("product-name");const productDescription=document.getElementById("product-description");const productPrice=document.getElementById("product-price");const stickyPrice=document.getElementById("sticky-price");const specList=document.getElementById("spec-list");const reviewList=document.getElementById("review-list");const bundleGrid=document.getElementById("bundle-grid");const relatedGrid=document.getElementById("related-grid");const themeToggle=document.getElementById("theme-toggle");function updateSeo(product){document.title=`${product.name} | Fashion Hub`;document.querySelector('meta[name="description"]').setAttribute("content",`${product.name} is a premium ${product.category} piece from Fashion Hub featuring refined craftsmanship, modern style, and elevated comfort.`);document.querySelector('link[rel="canonical"]').setAttribute("href",`https://fashionhub.com/product.html?id=${product.id}`);document.querySelector('meta[property="og:title"]').setAttribute("content",`${product.name} | Fashion Hub`);document.querySelector('meta[property="og:description"]').setAttribute("content",`${product.name} is a premium ${product.category} piece from Fashion Hub featuring refined craftsmanship, modern style, and elevated comfort.`);document.querySelector('meta[property="og:url"]').setAttribute("content",`https://fashionhub.com/product.html?id=${product.id}`);document.querySelector('meta[name="twitter:title"]').setAttribute("content",`${product.name} | Fashion Hub`);document.querySelector('meta[name="twitter:description"]').setAttribute("content",`${product.name} is a premium ${product.category} piece from Fashion Hub featuring refined craftsmanship, modern style, and elevated comfort.`);const schema={"@context":"https://schema.org","@type":"Product",name:product.name,description:product.description,image:["https://fashionhub.com/assets/og-image.svg"],brand:{"@type":"Brand",name:"Fashion Hub"},category:product.category,offers:{"@type":"Offer",priceCurrency:"USD",price:product.price,availability:"https://schema.org/InStock",url:`https://fashionhub.com/product.html?id=${product.id}`}};const existing=document.getElementById("product-schema");if(existing)existing.remove();const script=document.createElement("script");script.id="product-schema";script.type="application/ld+json";script.textContent=JSON.stringify(schema);document.head.appendChild(script);const breadcrumbSchema={"@context":"https://schema.org","@type":"BreadcrumbList",itemListElement:[{"@type":"ListItem",position:1,name:"Home",item:"https://fashionhub.com/"},{"@type":"ListItem",position:2,name:"Products",item:"https://fashionhub.com/index.html#featured"},{"@type":"ListItem",position:3,name:product.name,item:`https://fashionhub.com/product.html?id=${product.id}`}]};const breadcrumbScript=document.getElementById("breadcrumb-schema");if(breadcrumbScript)breadcrumbScript.remove();const breadcrumbJson=document.createElement("script");breadcrumbJson.id="breadcrumb-schema";breadcrumbJson.type="application/ld+json";breadcrumbJson.textContent=JSON.stringify(breadcrumbSchema);document.head.appendChild(breadcrumbJson)}backBtn.addEventListener("click",()=>history.back());themeToggle.addEventListener("click",()=>{document.body.classList.toggle("light-theme");themeToggle.textContent=document.body.classList.contains("light-theme")?"☀":"☾"});function renderProduct(product){breadcrumb.innerHTML=`\n    <a href="index.html">Home</a>\n    <span>/</span>\n    <a href="index.html#featured">Shop</a>\n    <span>/</span>\n    <span>${product.name}</span>\n  `;galleryMain.style.background=`linear-gradient(135deg, ${product.accent}, #ffffff22)`;galleryTitle.textContent=`${product.name} • ${product.tag}`;productTag.textContent=product.tag;productName.textContent=product.name;productDescription.textContent=product.description;productPrice.textContent=product.priceLabel;stickyPrice.textContent=product.priceLabel;galleryThumbs.innerHTML=[{label:"Front view",detail:`${product.name} in a polished silhouette`},{label:"Detail view",detail:"Crafted finish and premium texture"},{label:"Lifestyle view",detail:"Styled for everyday movement"}].map((item,index)=>`\n    <div class="thumb-card ${index===0?"active":""}">\n      <strong>${item.label}</strong>\n      <span class="hero-copy">${item.detail}</span>\n    </div>\n  `).join("");specList.innerHTML=`\n    <div class="spec-item"><strong>Material</strong><span>Premium leather and brushed finish</span></div>\n    <div class="spec-item"><strong>Fit</strong><span>Tailored to feel refined and effortless</span></div>\n    <div class="spec-item"><strong>Care</strong><span>Spot clean and store flat to preserve shape</span></div>\n  `;reviewList.innerHTML=`\n    <div class="review-item">\n      <div class="review-meta"><strong>Ava</strong><span>★★★★★</span></div>\n      <p>Exceptional finish and the perfect balance of structure and softness.</p>\n    </div>\n    <div class="review-item">\n      <div class="review-meta"><strong>Noah</strong><span>★★★★★</span></div>\n      <p>Elegant without feeling overdone, and the delivery felt very premium.</p>\n    </div>\n  `}function renderRelated(products,current){const related=products.filter(item=>item.id!==current.id).slice(0,3);relatedGrid.innerHTML=related.length?related.map(item=>`\n    <div class="related-card">\n      <strong>${item.name}</strong>\n      <p class="hero-copy">${item.description}</p>\n      <div class="price-row">\n        <span class="price">${item.priceLabel}</span>\n        <a class="btn btn-secondary" href="product.html?id=${item.id}">View</a>\n      </div>\n    </div>\n  `).join(""):'<p class="empty-state">No additional products to show.</p>';const bundle=related.slice(0,2);bundleGrid.innerHTML=bundle.length?bundle.map(item=>`\n    <div class="bundle-card">\n      <strong>${item.name}</strong>\n      <p class="hero-copy">${item.description}</p>\n      <span class="price">${item.priceLabel}</span>\n    </div>\n  `).join(""):'<p class="empty-state">Bundle suggestions coming soon.</p>'}async function init(){const products=await loadProducts();const product=getProductById(products,productId);if(!product){document.getElementById("product-page").innerHTML='<p class="empty-state">This product is unavailable right now.</p>';return}renderProduct(product);updateSeo(product);renderRelated(products,product)}init();